/// Explication du réglage dont le libellé affiché est `shown` (dans la
/// langue `lang` ou en français), s'il en existe une.
pub fn tip(lang: Lang, shown: &str) -> Option<&'static str> {
    let idx = match lang {
        Lang::Fr => 0,
        Lang::En => 1,
        Lang::Es => 2,
        Lang::De => 3,
    };
    TIPS.iter().find(|(k, _)| *k == shown || T(lang, k) == shown).map(|(_, t)| t[idx])
}

#[cfg(test)]
mod tests {
    use super::*;
    /// Chaque bulle porte sur un libellé réellement traduit, et le retrouve dans les 4 langues.
    #[test]
    fn bulles_trouvees_dans_toutes_les_langues() {
        for (k, t) in TIPS {
            assert!(t.iter().all(|x| !x.is_empty()), "{k}");
            for l in [Lang::Fr, Lang::En, Lang::Es, Lang::De] {
                let shown = crate::i18n::T(l, k);
                assert!(tip(l, shown).is_some(), "{k} ({l:?})");
            }
        }
    }
}
